solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
bool find_word(const char *const *g, size_t rows, const char *w, coordinate *s,
               coordinate *e) {
    size_t n = strlen(w);
    if (!n)
        return false;
    for (size_t r = 0; r < rows; r++)
        for (size_t c = 0; c < strlen(g[r]); c++)
            for (int dr = -1; dr <= 1; dr++)
                for (int dc = -1; dc <= 1; dc++) {
                    if (!dr && !dc)
                        continue;
                    size_t k;
                    for (k = 0; k < n; k++) {
                        long rr = (long)r + (long)k * dr, cc = (long)c + (long)k * dc;
                        if (rr < 0 || cc < 0 || (size_t)rr >= rows ||
                            (size_t)cc >= strlen(g[rr]) || g[rr][cc] != w[k])
                            break;
                    }
                    if (k == n) {
                        s->row = r;
                        s->column = c;
                        e->row = (size_t)((long)r + (long)(n - 1) * dr);
                        e->column = (size_t)((long)c + (long)(n - 1) * dc);
                        return true;
                    }
                }
    return false;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}

int main(void) {
    const char *grid[] = {"abc", "def", "ghi"};
    struct search_case {
        const char *word;
        size_t sr, sc, er, ec;
    };
    const struct search_case cases[] = {{"abc", 0, 0, 0, 2}, {"cba", 0, 2, 0, 0},
                                        {"adg", 0, 0, 2, 0}, {"gda", 2, 0, 0, 0},
                                        {"aei", 0, 0, 2, 2}, {"iea", 2, 2, 0, 0},
                                        {"ceg", 0, 2, 2, 0}, {"gec", 2, 0, 0, 2}};
    coordinate start, end;
    for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
        assert(find_word(grid, 3, cases[i].word, &start, &end));
        assert(start.row == cases[i].sr && start.column == cases[i].sc);
        assert(end.row == cases[i].er && end.column == cases[i].ec);
    }
    assert(!find_word(grid, 3, "zzz", &start, &end));
    assert(!find_word(grid, 3, "ABC", &start, &end)); /* Match characters exactly. */
    assert(!find_word(grid, 3, "", &start, &end));
    assert(!find_word(grid, 3, "abcd", &start, &end)); /* Never wrap across rows. */
    assert(!find_word(NULL, 0, "a", &start, &end));
    assert(find_word(grid, 3, "e", &start, &end) && start.row == 1 &&
           start.column == 1 && end.row == 1 && end.column == 1);
    const char *ragged[] = {"ab", "c", "def"};
    assert(!find_word(ragged, 3, "be", &start, &end));
    assert(find_word(ragged, 3, "acd", &start, &end) && end.row == 2 &&
           end.column == 0);

    return 0;
}
